class Solution {
  public int maxIncreasingSubarrays(List<Integer> nums) {
    int best = 0, prev = 0, cur = 1;
    for (int i = 1; i <= nums.size(); i++) {
      if (i < nums.size() && nums.get(i) > nums.get(i - 1)) {
        cur++;
        continue;
      }
      // a strictly increasing run ended: split it in half, or pair it with the previous run
      best = Math.max(best, Math.max(cur / 2, Math.min(prev, cur)));
      prev = cur;
      cur = 1;
    }
    return best;
  }
}
